"use strict";
// Shared helpers for the dashboard shell and every panel. Shipped; learners do not edit this file.
//
// What the dashboard reads (written by `python -m harness`, served by /api/runs):
//   run.json     run_id, parent, change, kind, label, settings, manifest, fingerprint, totals (or overall),
//                slices. A metric under totals is a number, or {value, n}, or {num, den}.
//   cases.jsonl  one line per case: id, kind (question | attack), family, slices, expected_action, must_pass,
//                passed, failure_type, recall3, recall5, rr, context_fact_recall (or fact_recall),
//                context_tokens, cost_usd, latency_ms, tool_ok, steps[].eval (the eval block of each step).
// A missing field is shown as "n/a" (not applicable), never as 0% and never as 100%.
(function () {
  const SVG = "http://www.w3.org/2000/svg";

  // ---- DOM ------------------------------------------------------------------------------------
  function el(tag, props, ...kids) {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(props || {})) {
      if (v == null) continue;
      if (k === "class") n.className = v;
      else if (k === "text") n.textContent = v;
      else if (k === "style") n.setAttribute("style", v);
      else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v);
    }
    for (const kid of kids.flat()) if (kid != null && kid !== false) n.append(kid);
    return n;
  }
  function svg(tag, props, ...kids) {
    const n = document.createElementNS(SVG, tag);
    for (const [k, v] of Object.entries(props || {})) {
      if (k === "text") n.textContent = v; else n.setAttribute(k, v);
    }
    for (const kid of kids.flat()) if (kid != null) n.append(kid);
    return n;
  }

  // ---- numbers --------------------------------------------------------------------------------
  const NA = "n/a";
  const isNum = (x) => typeof x === "number" && isFinite(x);
  const int = (x) => (isNum(x) ? Math.round(x).toLocaleString("en-US") : NA);
  const pct = (x, d = 0) => (isNum(x) ? (x * 100).toFixed(d) + "%" : NA);
  const num = (x, d = 3) => (isNum(x) ? x.toFixed(d) : NA);
  const sec = (ms) => (isNum(ms) ? (ms / 1000).toFixed(1) + " s" : NA);
  const tok = (x) => (isNum(x) ? int(x) + " tokens" : NA);
  const usd = (x) => {
    if (!isNum(x)) return NA;
    if (x === 0) return "$0";
    return "$" + (x < 0.01 ? x.toFixed(5) : x.toFixed(4));
  };
  const nOf = (n) => (isNum(n) ? "n = " + n : NA);
  function mean(values) {
    const v = values.filter(isNum);
    return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
  }
  function percentile(values, p) {            // nearest rank
    const v = values.filter(isNum).sort((a, b) => a - b);
    if (!v.length) return null;
    return v[Math.max(0, Math.ceil((p / 100) * v.length) - 1)];
  }
  function median(values) { return percentile(values, 50); }

  // Two-sided exact sign test; ties are dropped before the call.
  function signTest(fixed, broken) {
    const n = fixed + broken;
    if (n === 0) return 1;
    const k = Math.min(fixed, broken);
    let p = 0, c = 1;                              // c = n choose i, built up
    for (let i = 0; i <= k; i++) { p += c; c = (c * (n - i)) / (i + 1); }
    return Math.min(1, (2 * p) / Math.pow(2, n));
  }

  // ---- reading runs ---------------------------------------------------------------------------
  const ALIASES = {
    answer_success: ["answer_success"],
    cited_correctly: ["cited_correctly"],
    recall5: ["recall5", "recall_at_5"],
    recall3: ["recall3", "recall_at_3"],
    mrr: ["mrr"],
    context_fact_recall: ["context_fact_recall", "fact_recall"],
    context_tokens: ["context_tokens", "context_tokens_mean"],
    security_pass_rate: ["security_pass_rate"],
    cost_p50: ["cost_p50", "cost_per_answer_p50"],
    cost_p95: ["cost_p95", "cost_per_answer_p95"],
    latency_p50_ms: ["latency_p50_ms", "latency_p50"],
    latency_p95_ms: ["latency_p95_ms", "latency_p95"],
    tool_correctness: ["tool_correctness"],
    handoff_correctness: ["handoff_correctness"],
    false_handoff_rate: ["false_handoff_rate"],
    clarify_correctness: ["clarify_correctness"],
    false_clarify_rate: ["false_clarify_rate"],
    over_refusals: ["over_refusals"],
    must_pass_failures: ["must_pass_failures"],
  };

  function readValue(raw) {
    if (raw == null) return { value: null, n: null };
    if (isNum(raw)) return { value: raw, n: null };
    if (typeof raw === "object") {
      const n = isNum(raw.n) ? raw.n : isNum(raw.den) ? raw.den : null;
      let value = isNum(raw.value) ? raw.value : null;
      if (value == null && isNum(raw.num) && isNum(raw.den) && raw.den > 0) value = raw.num / raw.den;
      return { value, n, num: raw.num, den: raw.den, failed: raw.failed };
    }
    return { value: null, n: null };
  }

  function metric(run, key, cases) {
    const sources = [run && run.totals, run && run.overall].filter(Boolean);
    for (const names of [ALIASES[key] || [key]]) {
      for (const src of sources) {
        for (const name of names) if (src[name] != null) return readValue(src[name]);
      }
    }
    return derive(cases || (run && run._cases) || [])[key] || { value: null, n: null };
  }

  // ---- case fields ----------------------------------------------------------------------------
  const kindOf = (c) => c.kind || (c.family || /^a-/.test(c.id || "") ? "attack" : "question");
  const passedOf = (c) => (typeof c.passed === "boolean" ? c.passed : typeof c.pass === "boolean" ? c.pass
    : typeof c.ok === "boolean" ? c.ok : c.verdict === "pass" ? true : c.verdict === "fail" ? false : null);
  function finalEval(c) {
    if (Array.isArray(c.steps) && c.steps.length) {
      for (let i = c.steps.length - 1; i >= 0; i--) if (c.steps[i] && c.steps[i].eval) return c.steps[i].eval;
    }
    return c.eval || {};
  }
  const allEvals = (c) => (Array.isArray(c.steps) ? c.steps.map((s) => s && s.eval).filter(Boolean) : c.eval ? [c.eval] : []);
  const factRecallOf = (c) => (c.context_fact_recall != null ? c.context_fact_recall : c.fact_recall);
  const contextTokensOf = (c) => (c.context_tokens != null ? c.context_tokens : finalEval(c).delivered_tokens);
  const isAnswerable = (c) => kindOf(c) === "question" && ["answer", "tool"].includes(c.expected_action);

  // Best-effort metrics from stored cases, used when run.json has no totals. The harness's own numbers win.
  function derive(cases) {
    const out = {};
    const q = cases.filter(isAnswerable);
    const share = (rows, test) => {
      const elig = rows.filter((c) => test(c) !== null);
      return { value: elig.length ? elig.filter((c) => test(c)).length / elig.length : null, n: elig.length };
    };
    if (q.length) out.answer_success = share(q, passedOf);
    const attacks = cases.filter((c) => kindOf(c) === "attack");
    if (attacks.length) out.security_pass_rate = share(attacks, passedOf);
    for (const [key, f] of [["recall3", (c) => c.recall3], ["recall5", (c) => c.recall5], ["mrr", (c) => c.rr],
      ["context_fact_recall", factRecallOf], ["context_tokens", contextTokensOf]]) {
      const vals = cases.map(f).filter(isNum);
      if (vals.length) out[key] = { value: mean(vals), n: vals.length };
    }
    const costs = cases.map((c) => c.cost_usd).filter(isNum);
    if (costs.length) {
      out.cost_p50 = { value: percentile(costs, 50), n: costs.length };
      if (costs.length >= 20) out.cost_p95 = { value: percentile(costs, 95), n: costs.length };
    }
    const eq = cases.map((c) => c.hosted_equivalent_usd).filter(isNum);
    if (eq.length) out.hosted_equivalent_cost_p50 = { value: percentile(eq, 50), n: eq.length };
    const lat = cases.map((c) => c.latency_ms).filter(isNum);
    if (lat.length) {
      out.latency_p50_ms = { value: percentile(lat, 50), n: lat.length };
      if (lat.length >= 20) out.latency_p95_ms = { value: percentile(lat, 95), n: lat.length };
    }
    const mp = cases.filter((c) => c.must_pass);
    out.must_pass_failures = { value: mp.filter((c) => passedOf(c) === false).length, n: mp.length,
      failed: mp.filter((c) => passedOf(c) === false).map((c) => c.id) };
    return out;
  }

  function changeText(run) {
    const ch = run.change;
    if (typeof ch === "string" && ch) return ch;
    if (ch && typeof ch === "object") {
      const k = ch.setting || ch.key || ch.name;
      if (k && ("from" in ch || "to" in ch)) return k + ": " + ch.from + " -> " + ch.to;
      if (k) return k + " = " + (ch.value != null ? ch.value : ch.to);
      return JSON.stringify(ch);
    }
    if (run.label) return run.label;
    if (run.kind === "screen" && run.config) {
      return ["chunker", "chunk_size", "overlap", "retriever"].filter((k) => k in run.config)
        .map((k) => k + "=" + run.config[k]).join(", ");
    }
    return NA;
  }
  const modelPathOf = (run) => (run.settings && run.settings.model_path) || run.model_path || (run.kind === "screen" ? "no model" : NA);

  // ---- tables ---------------------------------------------------------------------------------
  // columns: [{label, key, num, fmt(value,row) -> string|Node, title}]
  function table(opts) {
    const { columns, rows, caption, onRowClick, rowKey, selected, empty } = opts;
    if (!rows.length) return el("p", { class: "muted", text: empty || "Nothing to show yet." });
    const head = el("tr", {}, columns.map((c) => el("th", { scope: "col", class: c.num ? "num" : "", title: c.title },
      c.label)));
    const body = rows.map((row) => {
      const tr = el("tr", { class: (onRowClick ? "clickable " : "") + (rowKey && selected === rowKey(row) ? "selected" : ""),
        tabindex: onRowClick ? "0" : null });
      if (onRowClick) {
        tr.addEventListener("click", () => onRowClick(row));
        tr.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onRowClick(row); } });
      }
      for (const c of columns) {
        const raw = c.key ? row[c.key] : undefined;
        const shown = c.fmt ? c.fmt(raw, row) : raw == null ? NA : String(raw);
        tr.append(el("td", { class: c.num ? "num" : "" }, shown));
      }
      return tr;
    });
    const t = el("table", {}, caption ? el("caption", { text: caption }) : null, el("thead", {}, head), el("tbody", {}, body));
    return el("div", { class: "table-wrap" }, t);
  }

  // A table whose last column draws a bar, so a chart is also a table with real labels.
  // rows: [{label, value (0..max), n, text}]; the title says what the bars show.
  function barTable(title, rows, opts) {
    const o = Object.assign({ max: 1, valueLabel: "Value", fmt: (v) => pct(v) }, opts);
    const cols = [
      { label: o.rowLabel || "Group", key: "label" },
      { label: "n", key: "n", num: true, fmt: (v) => (isNum(v) ? int(v) : NA) },
      { label: o.valueLabel, key: "value", num: true, fmt: (v, r) => (r.text != null ? r.text : o.fmt(v)) },
      { label: title, key: "value", fmt: (v) => el("div", { class: "bar-track", role: "img",
        "aria-label": isNum(v) ? o.fmt(v) : NA }, isNum(v) ? el("div", { class: "bar-fill",
          style: "width:" + Math.max(0, Math.min(100, (v / o.max) * 100)).toFixed(1) + "%" }) : null) },
    ];
    return table({ caption: title, columns: cols, rows, empty: o.empty });
  }

  // A scatter plot in SVG: one point per run. points: [{label, x, y, current}]
  function scatter(title, points, opts) {
    const o = Object.assign({ xLabel: "x", yLabel: "y", xFmt: (v) => String(v), yFmt: (v) => String(v) }, opts);
    const pts = points.filter((p) => isNum(p.x) && isNum(p.y));
    const W = 340, H = 250, L = 52, R = 14, T = 12, B = 44;
    const wrap = el("figure", { class: "chart" }, el("figcaption", { text: title }));
    if (!pts.length) { wrap.append(el("p", { class: "muted", text: "No run has both numbers yet (n/a)." })); return wrap; }
    const span = (vals, pad) => {
      let lo = Math.min(...vals), hi = Math.max(...vals);
      if (lo === hi) { lo -= 1; hi += 1; }
      const d = (hi - lo) * pad; return [lo - d, hi + d];
    };
    const [x0, x1] = span(pts.map((p) => p.x), 0.08), [y0, y1] = span(pts.map((p) => p.y), 0.08);
    const sx = (v) => L + ((v - x0) / (x1 - x0)) * (W - L - R);
    const sy = (v) => H - B - ((v - y0) / (y1 - y0)) * (H - B - T);
    const s = svg("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": title, class: "scatter" });
    for (let i = 0; i <= 4; i++) {
      const xv = x0 + ((x1 - x0) * i) / 4, yv = y0 + ((y1 - y0) * i) / 4;
      s.append(svg("line", { x1: sx(xv), x2: sx(xv), y1: T, y2: H - B, class: "grid" }),
        svg("line", { x1: L, x2: W - R, y1: sy(yv), y2: sy(yv), class: "grid" }),
        svg("text", { x: sx(xv), y: H - B + 14, class: "tick", "text-anchor": "middle", text: o.xFmt(xv) }),
        svg("text", { x: L - 6, y: sy(yv) + 4, class: "tick", "text-anchor": "end", text: o.yFmt(yv) }));
    }
    s.append(svg("text", { x: (L + W - R) / 2, y: H - 6, class: "axis", "text-anchor": "middle", text: o.xLabel }),
      svg("text", { x: 12, y: (T + H - B) / 2, class: "axis", "text-anchor": "middle",
        transform: `rotate(-90 12 ${(T + H - B) / 2})`, text: o.yLabel }));
    for (const p of pts) {
      s.append(svg("circle", { cx: sx(p.x), cy: sy(p.y), r: p.current ? 6 : 4, class: p.current ? "pt current" : "pt" },
        svg("title", { text: `${p.label}: ${o.xLabel} ${o.xFmt(p.x)}, ${o.yLabel} ${o.yFmt(p.y)}` })),
        svg("text", { x: sx(p.x) + 7, y: sy(p.y) - 6, class: "ptlabel", text: p.label }));
    }
    wrap.append(s);
    return wrap;
  }

  function note(text) { return el("p", { class: "muted", text }); }

  window.DashLib = { el, svg, NA, isNum, int, pct, num, sec, tok, usd, nOf, mean, median, percentile, signTest,
    metric, readValue, derive, kindOf, passedOf, finalEval, allEvals, factRecallOf, contextTokensOf, isAnswerable,
    changeText, modelPathOf, table, barTable, scatter, note };
})();
